import express, { Request, Response } from 'express';

const app = express();
app.use(express.json());

interface Article {
  id: string;
  title: string;
  content: string;
}

const articlesDb = new Map<string, Article>();

// Safe & Idempotent: GET chỉ đọc, không biến đổi state
app.get('/api/v1/articles/:id', (req: Request, res: Response) => {
  const article = articlesDb.get(req.params.id);
  if (!article) return res.status(404).json({ error: 'NotFound' });
  return res.status(200).json(article);
});

// Idempotent (nhưng NOT Safe): PUT ghi đè toàn bộ resource
// Gọi 1 lần hay 100 lần cùng payload thì resource trong DB vẫn y hệt
app.put('/api/v1/articles/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  const { title, content } = req.body;
  const updated: Article = { id, title, content };
  articlesDb.set(id, updated);
  return res.status(200).json(updated);
});

// Non-idempotent: POST tạo mới resource hoặc append dữ liệu
// Mỗi lần gọi sẽ sinh ra một bản ghi mới với ID mới
app.post('/api/v1/articles', (req: Request, res: Response) => {
  const newId = crypto.randomUUID();
  const article: Article = { id: newId, title: req.body.title, content: req.body.content };
  articlesDb.set(newId, article);
  return res.status(201).header('Location', `/api/v1/articles/${newId}`).json(article);
});

