import express, { Request, Response } from 'express';

const app = express();
app.use(express.json());

interface UserProfile {
  name: string;
  bio?: string | null;
  tags: string[];
}

let user: UserProfile = { name: "Nam Nguyen", bio: "Backend dev", tags: ["node", "sql"] };

// 1. JSON Merge Patch (RFC 7396) - Content-Type: application/merge-patch+json
// Payload: { "bio": null, "name": "Nam N." } => null hiểu là xoá bio
app.patch('/api/v1/users/profile/merge', (req: Request, res: Response) => {
  const patch = req.body;
  for (const [key, val] of Object.entries(patch)) {
    if (val === null) {
      delete (user as any)[key]; // Xoá trường
    } else {
      (user as any)[key] = val; // Cập nhật hoặc thêm trường
    }
  }
  return res.json(user);
});

// 2. JSON Patch (RFC 6902) - Content-Type: application/json-patch+json
// Payload: [
//   { "op": "test", "path": "/name", "value": "Nam Nguyen" },
//   { "op": "replace", "path": "/name", "value": "Nam N." },
//   { "op": "add", "path": "/tags/0", "value": "docker" }
// ]
app.patch('/api/v1/users/profile/json-patch', (req: Request, res: Response) => {
  const operations = req.body as Array<{ op: string; path: string; value?: any }>;
  for (const op of operations) {
    if (op.op === 'test' && op.path === '/name' && user.name !== op.value) {
      return res.status(409).json({ error: 'Precondition Failed: /name mismatch' });
    }
    if (op.op === 'replace' && op.path === '/name') {
      user.name = op.value;
    }
    if (op.op === 'add' && op.path === '/tags/0') {
      user.tags.unshift(op.value);
    }
  }
  return res.json(user);
});

