import express, { Request, Response } from 'express';

const app = express();
app.use(express.json());

// Case 1: Đồng bộ tạo mới tài nguyên -> 201 Created + Location header
app.post('/api/v1/orders', async (req: Request, res: Response) => {
  const newOrderId = 'ord_' + crypto.randomUUID();
  const order = { id: newOrderId, total: req.body.total, status: 'CONFIRMED' };

  // Lưu vào database đồng bộ...
  const canonicalUrl = `/api/v1/orders/${newOrderId}`;
  return res
    .status(201)
    .header('Location', canonicalUrl)
    .json({ data: order });
});

// Case 2: Bất đồng bộ (Async Job / Batch Task) -> 202 Accepted + Job Location
app.post('/api/v1/reports/export', async (req: Request, res: Response) => {
  const jobId = 'job_' + crypto.randomUUID();
  // Đẩy task vào RabbitMQ / Redis BullMQ
  // await queue.add('export-report', { jobId, filter: req.body });

  const jobStatusUrl = `/api/v1/jobs/${jobId}`;
  return res
    .status(202)
    .header('Location', jobStatusUrl)
    .json({
      message: 'Report generation started in background.',
      jobId,
      statusUrl: jobStatusUrl
    });
});

