import express, { Request, Response, NextFunction } from 'express';
import { z, ZodError } from 'zod';

const app = express();
app.use(express.json());

const RegisterSchema = z.object({
  email: z.string().email(),
  age: z.number().int().min(18),
});

const existingUsers = new Set(['admin@company.com']);

app.post('/api/v1/auth/register', async (req: Request, res: Response) => {
  // 1. Kiểm tra 422: Validate định dạng và logic dữ liệu
  const parseResult = RegisterSchema.safeParse(req.body);
  if (!parseResult.success) {
    return res.status(422).json({
      type: 'https://example.com/errors/unprocessable-entity',
      title: 'Validation Failed',
      status: 422,
      errors: parseResult.error.flatten().fieldErrors
    });
  }

  const { email } = parseResult.data;

  // 2. Kiểm tra 409: Xung đột trạng thái tài nguyên đã có trong DB
  if (existingUsers.has(email.toLowerCase())) {
    return res.status(409).json({
      type: 'https://example.com/errors/conflict',
      title: 'Resource Conflict',
      status: 409,
      detail: `User with email '${email}' already exists.`
    });
  }

  existingUsers.add(email.toLowerCase());
  return res.status(201).json({ email, status: 'ACTIVE' });
});

// 3. Global Error Handler bắt lỗi 400 (Malformed JSON do client gửi sai cú pháp)
app.use((err: any, req: Request, res: Response, next: NextFunction) => {
  if (err instanceof SyntaxError && 'body' in err) {
    return res.status(400).json({
      type: 'https://example.com/errors/bad-request',
      title: 'Malformed JSON Request',
      status: 400,
      detail: 'Request body contains invalid JSON syntax.'
    });
  }
  return res.status(500).json({ title: 'Internal Server Error', status: 500 });
});

