import { Pool, PoolClient } from 'pg';

interface CreateOrderInput {
  userId: string;
  totalAmount: number;
}

export async function createOrderWithOutbox(pool: Pool, input: CreateOrderInput) {
  const client: PoolClient = await pool.connect();
  try {
    // Bắt đầu Local Database Transaction
    await client.query('BEGIN');

    // 1. Ghi dữ liệu nghiệp vụ chính
    const orderId = crypto.randomUUID();
    const insertOrderQuery = `
      INSERT INTO orders (id, user_id, total_amount, status, created_at)
      VALUES ($1, $2, $3, 'PENDING', NOW())
      RETURNING *;
    `;
    const orderResult = await client.query(insertOrderQuery, [orderId, input.userId, input.totalAmount]);
    const createdOrder = orderResult.rows[0];

    // 2. Ghi Event vào bảng Outbox TRONG CÙNG TRANSACTION (Đảm bảo All-or-Nothing)
    const outboxEvent = {
      id: crypto.randomUUID(),
      aggregateType: 'ORDER',
      aggregateId: orderId,
      eventType: 'OrderCreated',
      payload: JSON.stringify(createdOrder),
    };

    const insertOutboxQuery = `
      INSERT INTO outbox_events (id, aggregate_type, aggregate_id, event_type, payload, status, created_at)
      VALUES ($1, $2, $3, $4, $5, 'UNPUBLISHED', NOW());
    `;
    await client.query(insertOutboxQuery, [
      outboxEvent.id,
      outboxEvent.aggregateType,
      outboxEvent.aggregateId,
      outboxEvent.eventType,
      outboxEvent.payload
    ]);

    // Commit cả 2 thao tác nguyên tử
    await client.query('COMMIT');
    return createdOrder;
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }
}

