import { PoolClient } from 'pg';

interface PaymentMessage {
  eventId: string;
  transactionRef: string; // Business Natural Key
  userId: string;
  amount: number;
}

export async function processPaymentConsumer(client: PoolClient, message: PaymentMessage) {
  try {
    await client.query('BEGIN');

    // 1. Atomic Dedup Key Check & Lock bằng Unique Constraint
    // Thử insert vào bảng đã xử lý. Nếu đã có -> ON CONFLICT DO NOTHING
    const insertDedupQuery = `
      INSERT INTO processed_events (dedup_key, event_type, created_at)
      VALUES ($1, 'PAYMENT_CREDIT', NOW())
      ON CONFLICT (dedup_key) DO NOTHING
      RETURNING dedup_key;
    `;
    const dedupRes = await client.query(insertDedupQuery, [message.transactionRef]);

    // Nếu không return dòng nào nghĩa là message này ĐÃ TỪNG ĐƯỢC XỬ LÝ
    if (dedupRes.rows.length === 0) {
      console.warn(`[IDEMPOTENT] Duplicate event ignored: ${message.transactionRef}`);
      await client.query('ROLLBACK');
      return { status: 'DUPLICATE_IGNORED' };
    }

    // 2. Thực hiện business logic chính: Cộng tiền vào ví user
    const updateBalanceQuery = `
      UPDATE wallets 
      SET balance = balance + $1, updated_at = NOW()
      WHERE user_id = $2;
    `;
    await client.query(updateBalanceQuery, [message.amount, message.userId]);

    await client.query('COMMIT');
    return { status: 'PROCESSED_SUCCESSFULLY' };
  } catch (error) {
    await client.query('ROLLBACK');
    throw error; // Quăng lỗi để broker retry lại sau nếu là lỗi tạm thời (DB crash/timeout)
  }
}

