// Database Schema (PostgreSQL):
// CREATE TABLE transactions (
//   id UUID PRIMARY KEY,
//   amount NUMERIC(15, 4) NOT NULL,
//   currency VARCHAR(3) NOT NULL, -- Chuẩn ISO 4217 (USD, VND, EUR)
//   base_currency VARCHAR(3) NOT NULL DEFAULT 'USD',
//   exchange_rate NUMERIC(12, 6) NOT NULL DEFAULT 1.000000,
//   amount_in_base NUMERIC(15, 4) NOT NULL,
//   created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
// );

import Decimal from 'decimal.js'; // Sử dụng thư viện Arbitrary-precision thay vì float nguyên thuỷ của JS

export interface Money {
  amount: Decimal;
  currency: string;
}

export class MoneyOperations {
  // Cộng tiền cùng loại tiền tệ
  static add(a: Money, b: Money): Money {
    if (a.currency !== b.currency) {
      throw new Error(`Currency mismatch: cannot add ${a.currency} and ${b.currency}`);
    }
    return {
      amount: a.amount.plus(b.amount),
      currency: a.currency,
    };
  }

  // Chuyển đổi ngoại tệ với tỷ giá kiểm toán
  static convert(money: Money, targetCurrency: string, rate: Decimal): Money {
    // Rounding Half-Up theo quy chuẩn kế toán quốc tế
    const convertedAmount = money.amount.mul(rate).toDecimalPlaces(4, Decimal.ROUND_HALF_UP);
    return {
      amount: convertedAmount,
      currency: targetCurrency,
    };
  }
}

