import Redis from 'ioredis';

const redis = new Redis();

// Thuật toán Sliding Window Counter bằng Redis Pipeline (Tối ưu Memory & Race Condition)
export async function isRateLimited(key: string, limit: number, windowSeconds: number): Promise<{ allowed: boolean; remaining: number }> {
  const now = Date.now();
  const windowStart = now - windowSeconds * 1000;
  const redisKey = `ratelimit:${key}`;

  const pipeline = redis.pipeline();
  // 1. Xoá các timestamp nằm ngoài cửa sổ thời gian
  pipeline.zremrangebyscore(redisKey, 0, windowStart);
  // 2. Thêm timestamp hiện tại vào Sorted Set (dùng microsecond/random để tránh trùng score)
  pipeline.zadd(redisKey, now, `${now}-${Math.random()}`);
  // 3. Đếm số lượng request trong khung thời gian hiện tại
  pipeline.zcard(redisKey);
  // 4. Set TTL tự động dọn dẹp key
  pipeline.expire(redisKey, windowSeconds);

  const results = await pipeline.exec();
  const requestCount = (results?.[2]?.[1] as number) || 0;

  if (requestCount > limit) {
    return { allowed: false, remaining: 0 };
  }

  return { allowed: true, remaining: limit - requestCount };
}

