import express, { Request, Response, NextFunction } from 'express';
import Redis from 'ioredis';

const redis = new Redis();
const app = express();
app.use(express.json());

export async function idempotencyMiddleware(req: Request, res: Response, next: NextFunction) {
  const idempotencyKey = req.header('Idempotency-Key');
  if (!idempotencyKey) return next();

  const cacheKey = `idempotency:${idempotencyKey}`;

  // 1. Thử đặt trạng thái IN_FLIGHT (Lock trong 30s)
  const acquired = await redis.set(cacheKey, JSON.stringify({ state: 'IN_FLIGHT' }), 'EX', 30, 'NX');

  if (!acquired) {
    const cachedData = await redis.get(cacheKey);
    if (!cachedData) return res.status(409).json({ error: 'Concurrent request in progress' });

    const parsed = JSON.parse(cachedData);
    if (parsed.state === 'IN_FLIGHT') {
      return res.status(409).json({ error: 'A request with this Idempotency-Key is currently being processed.' });
    }

    // Đã hoàn thành trước đó -> Phục vụ lại kết quả y hệt (Status + Body)
    return res.status(parsed.statusCode).json(parsed.body);
  }

  // Intercept res.json để tự động lưu kết quả vào cache
  const originalJson = res.json.bind(res);
  res.json = (body: any) => {
    redis.set(cacheKey, JSON.stringify({
      state: 'COMPLETED',
      statusCode: res.statusCode,
      body
    }), 'EX', 86400); // Lưu cache 24h
    return originalJson(body);
  };

  next();
}

