import express, { Request, Response } from 'express';
import { Pool } from 'pg';

const pool = new Pool();
const app = express();

interface CursorPayload {
  createdAt: string;
  id: string;
}

// Cursor-based Pagination Endpoint
app.get('/api/v1/posts', async (req: Request, res: Response) => {
  const limit = Math.min(parseInt(req.query.limit as string) || 20, 100);
  const cursor = req.query.cursor as string | undefined;

  let query = '';
  let params: any[] = [];

  if (!cursor) {
    // Trang đầu tiên
    query = `
      SELECT id, title, created_at
      FROM posts
      ORDER BY created_at DESC, id DESC
      LIMIT $1;
    `;
    params = [limit + 1]; // Lấy thêm 1 bản ghi để biết có next page hay không
  } else {
    // Giải mã cursor từ Base64: "createdAt_id"
    const decoded = Buffer.from(cursor, 'base64').toString('utf8');
    const [lastCreatedAt, lastId] = decoded.split('_');

    // Keyset pagination sử dụng Tuple so sánh index: (created_at, id) < ($1, $2)
    query = `
      SELECT id, title, created_at
      FROM posts
      WHERE (created_at, id) < ($1, $2)
      ORDER BY created_at DESC, id DESC
      LIMIT $3;
    `;
    params = [lastCreatedAt, lastId, limit + 1];
  }

  const result = await pool.query(query, params);
  const hasMore = result.rows.length > limit;
  const items = hasMore ? result.rows.slice(0, limit) : result.rows;

  let nextCursor: string | null = null;
  if (hasMore) {
    const lastItem = items[items.length - 1];
    nextCursor = Buffer.from(`${lastItem.created_at.toISOString()}_${lastItem.id}`).toString('base64');
  }

  return res.json({
    data: items,
    pagination: {
      hasMore,
      nextCursor
    }
  });
});

