import express, { Request, Response, NextFunction } from 'express';

export interface ProblemDetails {
  type: string;        // URI reference identifying the problem type
  title: string;       // Short, human-readable summary
  status: number;      // HTTP status code
  detail?: string;     // Explanation specific to this occurrence
  instance?: string;   // URI identifying the specific occurrence of problem
  invalidParams?: Array<{ name: string; reason: string }>; // Extension field
}

export class ApiError extends Error {
  constructor(
    public status: number,
    public title: string,
    public detail: string,
    public typeUri: string = 'about:blank',
    public invalidParams?: Array<{ name: string; reason: string }>
  ) {
    super(detail);
  }
}

export function rfc9457ErrorHandler(err: Error, req: Request, res: Response, next: NextFunction) {
  const traceId = (req.headers['x-request-id'] as string) || crypto.randomUUID();

  if (err instanceof ApiError) {
    const problem: ProblemDetails = {
      type: err.typeUri,
      title: err.title,
      status: err.status,
      detail: err.detail,
      instance: `/errors/${traceId}`,
      invalidParams: err.invalidParams
    };

    return res
      .status(err.status)
      .contentType('application/problem+json')
      .json(problem);
  }

  // 500 Unhandled Fallback
  const internalProblem: ProblemDetails = {
    type: 'https://api.example.com/errors/internal-server-error',
    title: 'Internal Server Error',
    status: 500,
    detail: 'An unexpected internal error occurred.',
    instance: `/errors/${traceId}`
  };

  return res.status(500).contentType('application/problem+json').json(internalProblem);
}

