import { Request, Response } from 'express';
import Redis from 'ioredis';
import { Pool } from 'pg';

const redis = new Redis();
const pool = new Pool();

export async function handlePayment(req: Request, res: Response) {
  const { orderId, amount } = req.body;
  const lockKey = `lock:payment:${orderId}`;

  // LỚP 1: Distributed Lock qua Redis (Thời gian lock 20s đủ để gọi Payment Gateway)
  const isAcquired = await redis.set(lockKey, 'LOCKED', 'EX', 20, 'NX');
  if (!isAcquired) {
    return res.status(409).json({
      error: 'Conflict',
      message: 'Payment is already processing for this order. Please wait.'
    });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // LỚP 2: Kiểm tra State Machine trong Database
    const orderRes = await client.query('SELECT status FROM orders WHERE id = $1 FOR UPDATE', [orderId]);
    if (orderRes.rows.length === 0 || orderRes.rows[0].status !== 'PENDING') {
      await client.query('ROLLBACK');
      return res.status(400).json({ error: 'Order is not eligible for payment.' });
    }

    // LỚP 3: Database Unique Constraint trên bảng payments (order_id UNIQUE)
    await client.query(
      'INSERT INTO payments (id, order_id, amount, status, created_at) VALUES ($1, $2, $3, $4, NOW())',
      [crypto.randomUUID(), orderId, amount, 'SUCCESS']
    );

    await client.query("UPDATE orders SET status = 'PAID' WHERE id = $1", [orderId]);

    await client.query('COMMIT');
    return res.status(200).json({ status: 'PAID', orderId });
  } catch (err: any) {
    await client.query('ROLLBACK');
    if (err.code === '23505') { // Postgres Unique Violation
      return res.status(409).json({ error: 'Duplicate payment detected.' });
    }
    return res.status(500).json({ error: 'Internal payment error.' });
  } finally {
    client.release();
    // Giải phóng lock Redis
    await redis.del(lockKey);
  }
}

