import express, { Request, Response, NextFunction } from 'express';

const app = express();

// Middleware cảnh báo Deprecation theo chuẩn IETF RFC 8594
export function deprecationNotice(sunsetDate: string, docUrl: string) {
  return (req: Request, res: Response, next: NextFunction) => {
    res.setHeader('Deprecation', 'true');
    res.setHeader('Sunset', sunsetDate); // e.g. "Wed, 01 Jan 2027 00:00:00 GMT"
    res.setHeader('Link', `<${docUrl}>; rel="deprecation"; type="text/html"`);
    next();
  };
}

// Router Version 1: Đã đánh dấu chuẩn bị khai tử
const v1Router = express.Router();
v1Router.use(deprecationNotice('Thu, 31 Dec 2026 23:59:59 GMT', 'https://docs.api.com/migration-v1-to-v2'));
v1Router.get('/users/:id', (req, res) => {
  // Trả format cũ: name là 1 chuỗi gộp
  return res.json({ id: req.params.id, name: 'Nam Nguyen' });
});

// Router Version 2: Format mới (Tách first_name, last_name)
const v2Router = express.Router();
v2Router.get('/users/:id', (req, res) => {
  return res.json({ id: req.params.id, firstName: 'Nam', lastName: 'Nguyen' });
});

app.use('/api/v1', v1Router);
app.use('/api/v2', v2Router);

