import express, { Request, Response, NextFunction } from 'express';
import Redis from 'ioredis';

const redis = new Redis();
const app = express();

export function standardRateLimiter(maxRequests: number, windowSeconds: number) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const clientId = req.ip || 'anonymous';
    const key = `rate:${clientId}`;

    const currentCount = await redis.incr(key);
    if (currentCount === 1) {
      await redis.expire(key, windowSeconds);
    }

    const ttl = await redis.ttl(key);
    const resetSeconds = ttl > 0 ? ttl : windowSeconds;

    // Gắn Headers chuẩn IETF cho mọi request
    res.setHeader('RateLimit-Limit', maxRequests);
    res.setHeader('RateLimit-Remaining', Math.max(0, maxRequests - currentCount));
    res.setHeader('RateLimit-Reset', resetSeconds);

    if (currentCount > maxRequests) {
      // Bị chặn: Trả mã 429 và thông báo Retry-After
      res.setHeader('Retry-After', resetSeconds);
      return res.status(429).json({
        type: 'https://example.com/errors/rate-limit-exceeded',
        title: 'Too Many Requests',
        status: 429,
        detail: `Quota exceeded. Please retry after ${resetSeconds} seconds.`
      });
    }

    return next();
  };
}

