import express, { Request, Response } from 'express';
import { Queue } from 'bullmq';

const app = express();
app.use(express.json());

const exportQueue = new Queue('export-reports', { connection: { host: 'localhost', port: 6379 } });

// 1. Tiếp nhận yêu cầu export: Trả 202 Accepted tức thì (< 50ms)
app.post('/api/v1/reports/export', async (req: Request, res: Response) => {
  const jobId = crypto.randomUUID();
  const { dateFrom, dateTo, format } = req.body;

  await exportQueue.add('generate-report', {
    jobId,
    userId: 'usr_123',
    params: { dateFrom, dateTo, format }
  }, { jobId });

  const statusUrl = `/api/v1/reports/jobs/${jobId}`;

  return res.status(202)
    .header('Location', statusUrl)
    .json({
      message: 'Export job accepted and currently queued.',
      jobId,
      statusUrl
    });
});

// 2. Polling Endpoint kiểm tra trạng thái Job
app.get('/api/v1/reports/jobs/:jobId', async (req: Request, res: Response) => {
  const job = await exportQueue.getJob(req.params.jobId);
  if (!job) return res.status(404).json({ error: 'Job not found' });

  const state = await job.getState();
  const progress = job.progress;

  if (state === 'completed') {
    return res.json({
      status: 'COMPLETED',
      progress: 100,
      downloadUrl: job.returnvalue.downloadUrl, // S3 Presigned URL
      expiresAt: job.returnvalue.expiresAt
    });
  }

  if (state === 'failed') {
    return res.status(500).json({
      status: 'FAILED',
      reason: job.failedReason
    });
  }

  return res.json({ status: state.toUpperCase(), progress });
});

