import express, { Request, Response } from 'express';

const app = express();
app.use(express.json());

interface InventoryItem {
  sku: string;
  quantity: number;
}

interface ItemResult {
  sku: string;
  status: number;
  message?: string;
}

app.patch('/api/v1/inventory/batch', async (req: Request, res: Response) => {
  const items: InventoryItem[] = req.body.items;
  const allOrNone = req.query.allOrNone === 'true';

  if (!Array.isArray(items) || items.length > 500) {
    return res.status(400).json({ error: 'Batch size must be between 1 and 500 items.' });
  }

  const results: ItemResult[] = [];
  let hasErrors = false;

  // Giả lập xử lý từng item
  for (const item of items) {
    if (item.quantity < 0) {
      results.push({ sku: item.sku, status: 422, message: 'Quantity cannot be negative.' });
      hasErrors = true;
    } else if (item.sku === 'UNKNOWN_SKU') {
      results.push({ sku: item.sku, status: 404, message: 'SKU not found.' });
      hasErrors = true;
    } else {
      results.push({ sku: item.sku, status: 200 });
    }
  }

  // Kịch bản 1: All-or-Nothing nguyên tử
  if (allOrNone && hasErrors) {
    return res.status(422).json({
      type: 'https://example.com/errors/batch-failure',
      title: 'Batch Update Rolled Back',
      status: 422,
      detail: 'One or more items failed validation. The entire transaction was aborted.',
      failedItems: results.filter(r => r.status !== 200)
    });
  }

  // Kịch bản 2: Partial Success theo chuẩn WebDAV RFC 4918 (207 Multi-Status)
  const httpStatus = hasErrors ? 207 : 200;
  return res.status(httpStatus).json({
    summary: {
      total: items.length,
      successCount: results.filter(r => r.status === 200).length,
      failureCount: results.filter(r => r.status !== 200).length
    },
    items: results
  });
});

