// Thuật toán Full Jitter Retry (Khuyến nghị chuẩn bởi AWS Architecture)
export async function retryWithBackoffAndJitter<T>(
  fn: () => Promise<T>,
  maxRetries: number = 5,
  baseDelayMs: number = 500,
  maxDelayMs: number = 10000
): Promise<T> {
  let attempt = 0;

  while (true) {
    try {
      return await fn();
    } catch (error: any) {
      attempt++;
      if (attempt > maxRetries) {
        console.error(`Exceeded max retries (${maxRetries}). Sending to DLQ...`);
        throw error; // Chuyển vào Dead Letter Queue
      }

      // 1. Tính toán Exponential Delay: base * 2^(attempt - 1)
      const exponentialDelay = Math.min(maxDelayMs, baseDelayMs * Math.pow(2, attempt - 1));

      // 2. Full Jitter: Chọn ngẫu nhiên từ 0 đến exponentialDelay
      const sleepDuration = Math.floor(Math.random() * exponentialDelay);

      console.warn(`Attempt ${attempt} failed. Retrying in ${sleepDuration}ms (Jittered). Error: ${error.message}`);
      await new Promise(resolve => setTimeout(resolve, sleepDuration));
    }
  }
}

