import { Kafka, EachBatchPayload } from 'kafkajs';
import { Pool } from 'pg';

const kafka = new Kafka({ clientId: 'order-consumer', brokers: ['localhost:9092'] });
const consumer = kafka.consumer({ groupId: 'order-processing-group' });
const pool = new Pool();

async function run() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'orders', fromBeginning: false });

  // Sử dụng eachBatch thay vì eachMessage để gom hàng loạt (Bulk Processing)
  await consumer.run({
    eachBatchAutoResolve: false,
    eachBatch: async ({ batch, resolveOffset, heartbeat, isRunning, isStale }: EachBatchPayload) => {
      const records = batch.messages.map(msg => JSON.parse(msg.value!.toString()));

      if (records.length === 0) return;

      // Gom toàn bộ batch insert vào Postgres 1 lần duy nhất thay vì N round-trips
      const client = await pool.connect();
      try {
        await client.query('BEGIN');

        // Batch Insert Query tối ưu hoá throughput
        const values: any[] = [];
        const placeholders = records.map((r, i) => {
          const offset = i * 3;
          values.push(r.orderId, r.userId, r.amount);
          return `($${offset + 1}, $${offset + 2}, $${offset + 3})`;
        }).join(', ');

        await client.query(`INSERT INTO orders (id, user_id, amount) VALUES ${placeholders}`, values);
        await client.query('COMMIT');

        // Đánh dấu offset của message cuối cùng trong batch
        const lastMessage = batch.messages[batch.messages.length - 1];
        resolveOffset(lastMessage.offset);
        await heartbeat(); // Gửi heartbeat tránh bị Kafka coi là chết
      } catch (err) {
        await client.query('ROLLBACK');
        throw err;
      } finally {
        client.release();
      }
    }
  });
}

