import express, { Request, Response, NextFunction } from 'express';

const app = express();

const ALLOWED_ORIGINS = new Set([
  'https://app.mydomain.com',
  'https://admin.mydomain.com',
  'http://localhost:3000' // Local development
]);

// CORS Middleware hỗ trợ credentials an toàn
app.use((req: Request, res: Response, next: NextFunction) => {
  const origin = req.headers.origin;

  if (origin && ALLOWED_ORIGINS.has(origin)) {
    // 1. Phải phản hồi lại chính xác Origin của client, KHÔNG DÙNG '*'
    res.setHeader('Access-Control-Allow-Origin', origin);
    // 2. Bắt buộc để cho phép trình duyệt gửi & nhận HttpOnly Cookie
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    // Báo cho cache proxy biết response biến đổi theo Origin
    res.setHeader('Vary', 'Origin');
  }

  // 3. Xử lý Preflight Request (OPTIONS)
  if (req.method === 'OPTIONS') {
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, PATCH, DELETE, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Requested-With, Idempotency-Key');
    res.setHeader('Access-Control-Max-Age', '86400'); // Cache Preflight trong 24h
    return res.status(204).end();
  }

  next();
});

