export interface InterServiceCommunicationMatrix {
  protocol: 'gRPC' | 'REST' | 'MessageQueue';
  useCases: string[];
  tradeOffs: { pros: string[]; cons: string[] };
}

export const communicationStrategy: Record<string, InterServiceCommunicationMatrix> = {
  gRPC: {
    protocol: 'gRPC',
    useCases: [
      'Giao tiếp internal giữa microservices (East-West traffic)',
      'High-throughput, Low-latency (vd Realtime Bidding, Fraud Detection)',
      'Polyglot microservices (Go gọi Node.js, Python gọi Java)'
    ],
    tradeOffs: {
      pros: ['Độ trễ thấp', 'HTTP/2 multiplexing', 'Strong contract với Protobuf'],
      cons: ['Khó debug bằng trình duyệt/Postman', 'Cần L7 Load Balancer hiểu HTTP/2']
    }
  },
  MessageQueue: {
    protocol: 'MessageQueue',
    useCases: [
      'Xử lý bất đồng bộ (OrderCreated -> Gửi email, Tích điểm, Báo kho)',
      'San phẳng tải đột biến (Traffic spike leveling)',
      'Event-Driven Architecture / Saga Pattern'
    ],
    tradeOffs: {
      pros: ['Decoupling hoàn toàn', 'Khả năng phục hồi cao', 'Backpressure tự nhiên'],
      cons: ['Eventual consistency', 'Khó trace luồng dữ liệu (cần Distributed Tracing)']
    }
  },
  REST: {
    protocol: 'REST',
    useCases: [
      'Public API cho Web/Mobile App (North-South traffic)',
