import express, { Request, Response } from 'express';

const mobileBffApp = express();

// Mobile BFF Endpoint: Trang chủ Mobile Dashboard
// Gom dữ liệu từ 3 microservices nội bộ thành 1 payload siêu gọn, tối ưu băng thông di động
mobileBffApp.get('/mobile-bff/v1/home', async (req: Request, res: Response) => {
  const userId = req.headers['x-user-id'] as string;

  // Gọi song song các internal microservices thông qua mạng riêng (Private VPC)
  const [profileRes, unreadRes, bannersRes] = await Promise.all([
    fetch(`http://user-service/internal/users/${userId}`).then(r => r.json()),
    fetch(`http://notification-service/internal/users/${userId}/unread-count`).then(r => r.json()),
    fetch(`http://marketing-service/internal/banners?platform=mobile`).then(r => r.json())
  ]);

  // Cắt gọt và format sẵn cho Widget hiển thị trên App Mobile
  const mobileViewModel = {
    user: {
      displayName: (profileRes as any).fullName,
      avatarUrl: (profileRes as any).thumbnailUrl // Ảnh kích thước nhỏ cho mobile
    },
    badge: {
      unreadNotifications: (unreadRes as any).count
    },
    banners: ((bannersRes as any).items || []).map((b: any) => ({
      id: b.id,
      imageUrl: b.mobileImageUrl,
      deepLink: b.appDeepLink
    }))
  };

  return res.json(mobileViewModel);
});

