import { PrismaClient, Prisma } from '@prisma/client';

const prisma = new PrismaClient();

// ❌ LỖ HỔNG NGUY HIỂM 1: Lạm dụng $queryRawUnsafe với cộng chuỗi
export async function vulnerableSearch(keyword: string) {
  // Kẻ tấn công truyền: keyword = "admin' OR '1'='1"
  return await prisma.$queryRawUnsafe(`SELECT * FROM "User" WHERE email = '${keyword}'`);
}

// ❌ LỖ HỔNG NGUY HIỂM 2: Ghép chuỗi trong ORDER BY (SQL không thể parameterize identifier)
export async function vulnerableSort(sortColumn: string) {
  // Kẻ tấn công truyền: sortColumn = "id; DROP TABLE "User";--"
  return await prisma.$queryRawUnsafe(`SELECT id, name FROM "User" ORDER BY ${sortColumn} ASC`);
}

// ✅ CÁCH KHẮC PHỤC 1: Sử dụng Tagged Template $queryRaw chuẩn (Tự động thành Prepared Statement)
export async function safeSearch(keyword: string) {
  return await prisma.$queryRaw`SELECT * FROM "User" WHERE email = ${keyword}`;
}

// ✅ CÁCH KHẮC PHỤC 2: Whitelist chặt chẽ khi bắt buộc phải dynamic identifier
const ALLOWED_COLUMNS: Record<string, Prisma.Sql> = {
  createdAt: Prisma.sql`"createdAt"`,
  name: Prisma.sql`"name"`,
  email: Prisma.sql`"email"`
};

export async function safeSort(userColumnInput: string) {
  const columnSql = ALLOWED_COLUMNS[userColumnInput] || ALLOWED_COLUMNS.createdAt;
  return await prisma.$queryRaw`SELECT id, name FROM "User" ORDER BY ${columnSql} ASC`;
}

