import path from 'path';
import sharp from 'sharp';
import { execFile } from 'child_process';
import { promisify } from 'util';

const execFileAsync = promisify(execFile);

// ❌ NGUY HIỂM: child_process.exec('convert ' + userFileName) => RCE tức thì!

// ✅ GIẢI PHÁP 1: Tối ưu & Chuẩn Production nhất bằng thư viện Native C++ (sharp)
export async function convertAvatarSecure(inputBuffer: Buffer, targetDir: string): Promise<string> {
  const safeFilename = `avatar_${crypto.randomUUID()}.webp`;
  const outputPath = path.join(targetDir, safeFilename);

  // Xử lý trực tiếp trong bộ nhớ qua libvips, không gọi shell, không lo command injection
  await sharp(inputBuffer)
    .resize(300, 300, { fit: 'cover' })
    .toFormat('webp', { quality: 80 })
    .toFile(outputPath);

  return safeFilename;
}

// ✅ GIẢI PHÁP 2: Nếu bắt buộc phải gọi binary CLI, dùng execFile và sanitize tên file
export async function runBinaryCliSecure(originalName: string, tempFilePath: string): Promise<string> {
  // 1. Tuyệt đối không dùng originalName trong đường dẫn đĩa, sinh UUID mới
  const safeId = crypto.randomUUID();
  const outputFilePath = path.join('/tmp', `${safeId}.png`);

  // 2. execFile không spawn shell, truyền arguments dạng Array tách biệt
  // Không ký tự metacharacter nào có thể biến thành lệnh shell
  await execFileAsync('/usr/bin/convert', [
    tempFilePath,
    '-resize', '300x300^',
    '-gravity', 'center',
    '-extent', '300x300',
    outputFilePath
  ]);

  return outputFilePath;
}

