import express, { Request, Response, NextFunction } from 'express';
import { z, ZodSchema } from 'zod';

const app = express();
app.use(express.json());

// 1. Shared Schema (dùng chung cho cả React Hook Form và Express)
export const CreateUserSchema = z.object({
  email: z.string().email('Invalid email format').toLowerCase(),
  password: z.string().min(8, 'Password must be at least 8 chars'),
  age: z.number().int().min(18, 'Must be at least 18 years old'),
  role: z.enum(['USER', 'EDITOR']).default('USER'), // Chặn client tự phong 'ADMIN'
}).strict(); // strict() loại bỏ hoàn toàn các trường lạ truyền lén (chống Mass Assignment)

export type CreateUserInput = z.infer<typeof CreateUserSchema>;

// 2. Generic Validation Middleware chuẩn xác ở Server
export function validateBody<T>(schema: ZodSchema<T>) {
  return (req: Request, res: Response, next: NextFunction) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      return res.status(422).json({
        type: 'https://example.com/errors/validation',
        title: 'Validation Error',
        status: 422,
        errors: result.error.flatten().fieldErrors
      });
    }

    // Gán lại req.body bằng dữ liệu ĐÃ ĐƯỢC PARSE & SANITIZE (ép kiểu, strip fields)
    req.body = result.data;
    next();
  };
}

// 3. Sử dụng trong Route
app.post('/api/v1/users', validateBody(CreateUserSchema), (req: Request, res: Response) => {
  const sanitizedInput: CreateUserInput = req.body;
  // An toàn tuyệt đối khi tương tác với DB
  return res.status(201).json({ email: sanitizedInput.email });
});

