import express, { Request, Response } from 'express';
import { PrismaClient } from '@prisma/client';
import { z } from 'zod';

const prisma = new PrismaClient();
const app = express();

// Output DTO Schema: Chỉ định nghĩa chính xác những trường ĐƯỢC PHÉP công khai
const UserPublicDto = z.object({
  id: z.string(),
  displayName: z.string(),
  email: z.string().email(),
  avatarUrl: z.string().nullable(),
  createdAt: z.date()
});

type UserPublicDto = z.infer<typeof UserPublicDto>;

app.get('/api/v1/users/:id', async (req: Request, res: Response) => {
  // ✅ GIẢI PHÁP TỐI ƯU: Chỉ SELECT đúng các trường công khai ngay từ Database
  // Giảm tải I/O đĩa, giảm RAM nạp record và loại bỏ nguy cơ lộ passwordHash
  const user = await prisma.user.findUnique({
    where: { id: req.params.id },
    select: {
      id: true,
      displayName: true,
      email: true,
      avatarUrl: true,
      createdAt: true,
      // passwordHash, twoFactorSecret, role BỊ BỎ QUA HOÀN TOÀN
    }
  });

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Validate qua DTO để đảm bảo contract luôn nhất quán
  const safeResponse: UserPublicDto = UserPublicDto.parse(user);
  return res.json(safeResponse);
});

