interface CursorData {
  createdAt: string; // ISO String
  id: string;        // UUID hoặc BigInt Tie-breaker
}

function encodeCursor(data: CursorData): string {
  return Buffer.from(JSON.stringify(data)).toString('base64url');
}

function decodeCursor(cursorStr: string): CursorData {
  return JSON.parse(Buffer.from(cursorStr, 'base64url').toString('utf8'));
}

app.get('/api/v1/feed', async (req: Request, res: Response) => {
  const limit = Math.min(Number(req.query.limit) || 20, 100);
  const cursorParam = req.query.cursor as string | undefined;

