import crypto from 'crypto';

interface WebhookEvent {
  id: string;
  eventType: string;
  payload: Record<string, any>;
}

// 1. Tạo chữ ký HMAC-SHA256 chống giả mạo và chống Replay Attack (Stripe Pattern)
export function signWebhookPayload(event: WebhookEvent, secretKey: string): { headerValue: string; rawBody: string } {
  const timestamp = Math.floor(Date.now() / 1000);
  const rawBody = JSON.stringify(event);

  // Ký trên cả timestamp và body để kẻ tấn công không thể tráo đổi thời gian
  const signedPayload = `${timestamp}.${rawBody}`;
  const signature = crypto
    .createHmac('sha256', secretKey)
    .update(signedPayload, 'utf8')
    .digest('hex');

  // Format header chuẩn: t=timestamp,v1=signature
  const headerValue = `t=${timestamp},v1=${signature}`;
  return { headerValue, rawBody };
}

// 2. Worker gửi Webhook với Timeout chặt chẽ
export async function dispatchWebhook(url: string, event: WebhookEvent, secret: string) {
  const { headerValue, rawBody } = signWebhookPayload(event, secret);

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 5000); // 5s timeout khắt khe

  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Webhook-Signature': headerValue,
        'X-Webhook-Id': event.id,
        'User-Agent': 'PaymentPlatform-Webhook/1.0'
      },
      body: rawBody,
      signal: controller.signal
    });

    if (!res.ok) {
      throw new Error(`Recipient returned HTTP ${res.status}`);
    }

    return { status: 'DELIVERED', statusCode: res.status };
  } finally {
    clearTimeout(timeoutId);
  }
}

