import express, { Request, Response } from 'express';

// Middleware Deadline Propagation
export function enforceDeadline(req: Request, res: Response, next: Function) {
  const deadlineHeader = req.header('X-Request-Deadline');
  const now = Date.now();

  let remainingBudgetMs = 3000; // Mặc định 3s nếu không có header
  if (deadlineHeader) {
    const deadlineTime = parseInt(deadlineHeader, 10);
    remainingBudgetMs = deadlineTime - now;

    if (remainingBudgetMs <= 0) {
      // Hết ngân sách thời gian -> Huỷ ngay lập tức!
      return res.status(504).json({ error: 'Deadline Exceeded: upstream already timed out.' });
    }
  }

  // Gán AbortController với thời gian timeout còn lại
  const abortController = new AbortController();
  const timer = setTimeout(() => abortController.abort(), remainingBudgetMs);

  res.locals.abortSignal = abortController.signal;
  res.locals.deadlineHeader = deadlineHeader || (now + remainingBudgetMs).toString();

  res.on('finish', () => clearTimeout(timer));
  next();
}

// Gọi Downstream Service kèm Deadline
export async function callDownstreamService(url: string, signal: AbortSignal, deadline: string) {
  return await fetch(url, {
    method: 'GET',
    headers: {
      'X-Request-Deadline': deadline, // Lan truyền tiếp xuống tầng sâu hơn
    },
    signal
  });
}

