// Thiết kế Saga Orchestrator cho Booking Flow
interface SagaStep {
  name: string;
  execute: () => Promise<void>;
  compensate: () => Promise<void>; // Hàm bù trừ BẮT BUỘC PHẢI IDEMPOTENT
}

export class BookingSagaOrchestrator {
  private executedSteps: SagaStep[] = [];

  async executeSaga(steps: SagaStep[]): Promise<boolean> {
    for (const step of steps) {
      try {
        console.log(`[SAGA] Executing step: ${step.name}`);
        await step.execute();
        this.executedSteps.push(step);
      } catch (stepError) {
        console.error(`[SAGA] Step ${step.name} failed! Starting Compensation Rollback...`);
        await this.rollback();
        return false;
      }
    }
    return true;
  }

  private async rollback(): Promise<void> {
    // Chạy ngược lại danh sách các bước đã thực hiện thành công
    const stepsToRevert = [...this.executedSteps].reverse();

    for (const step of stepsToRevert) {
      let compensated = false;
      let retries = 0;

      while (!compensated && retries < 5) {
        try {
          console.warn(`[SAGA-COMPENSATE] Reverting: ${step.name} (Attempt ${retries + 1})`);
          await step.compensate();
          compensated = true;
        } catch (compError: any) {
          retries++;
          console.error(`[CRITICAL] Compensation ${step.name} failed: ${compError.message}`);
          await new Promise(r => setTimeout(r, 1000 * Math.pow(2, retries))); // Exponential backoff
        }
      }

      // NẾU BƯỚC BÙ TRỪ VẪN THẤT BẠI SAU CÁC LẦN RETRY:
      if (!compensated) {
        // Ghi vào bảng SAGA_INCIDENTS khẩn cấp để kích hoạt PagerDuty cho Kỹ sư trực và Kế toán can thiệp
        await this.triggerHumanInterventionAlert(step.name);
      }
    }
  }

  private async triggerHumanInterventionAlert(stepName: string) {
    console.error(`🚨 [PAGERDUTY ALERT] Manual reconciliation required for Saga step: ${stepName}`);
    // Ghi DB audit log: INSERT INTO saga_failures (saga_id, step, status) VALUES (...)
  }
}

